mapper.select:
SELECT u.user_id AS userId, u.nickname, u.avatar, u.status, u.create_time AS createTime, i.phone, i.last_login_time AS lastLoginTime, a.identifier AS account, a.auth_type AS authType, (SELECT GROUP_CONCAT(r.role_name) FROM sys_role r JOIN sys_user_role ur ON r.role_id = ur.role_id WHERE ur.user_id = u.user_id) AS roleNames FROM sys_user u LEFT JOIN user_info i ON u.user_id = i.user_id LEFT JOIN user_auth a ON u.user_id = a.user_id
u.status != 2 AND u.nickname LIKE CONCAT('%', #{nickname}, '%')
AND i.phone = #{phone}
AND u.status = #{status}
AND a.auth_type = #{authType}
AND a.identifier LIKE CONCAT('%', #{identifier}, '%')
ORDER BY u.create_time DESC

mapper.update:
UPDATE sys_user
nickname = #{nickname}, avatar = #{avatar}, status = #{status},
WHERE user_id = #{userId}

UPDATE user_info
phone = #{phone}, gender = #{gender}, email = #{email}, city = #{city}, signature = #{signature},
WHERE user_id = #{userId}
